const anim = lottie.loadAnimation({
  container: document.getElementById('lottieContainer'),
  renderer: 'svg',
  loop: false,
  autoplay: false,
  animationData: lottieData
});
const playhead = { frame: 0 };
tl.to(playhead, {
  frame: anim.totalFrames - 1,
  duration: 3.0,
  ease: 'none',
  onUpdate: () => anim.goToAndStop(playhead.frame, true)
}, 0.5);

// Animate width of clipping rectangle to reveal graph
tl.fromTo('#clip-rect',
  { attr: { width: 0 } },
  { attr: { width: chartWidth }, duration: duration, ease: 'power1.inOut' },
  startTime
);

// Register dot position
tl.set('#signal-dot', { opacity: 0, attr: { cx: fromCoords.x, cy: fromCoords.y } }, startTime);
tl.to('#signal-dot', { opacity: 1, duration: 0.15 }, startTime);

// Travel along edge
tl.to('#signal-dot', {
  attr: { cx: toCoords.x, cy: toCoords.y },
  duration: travelDuration,
  ease: 'power1.inOut'
}, startTime + 0.15);

// Pulse target node on arrival
tl.to(targetSelector, {
  scale: 1.25,
  transformOrigin: '50% 50%',
  duration: 0.2,
  yoyo: true,
  repeat: 1,
  ease: 'power2.out'
}, startTime + 0.15 + travelDuration);

tl.to('#signal-dot', { opacity: 0, duration: 0.15 }, startTime + 0.15 + travelDuration + 0.1);

const canvas = document.getElementById('brushCanvas');
brush.load(canvas);
brush.scaleBrushes(1.2);

const anim = { progress: 0.01 };
tl.to(anim, {
  progress: 1.0,
  duration: 3.0,
  ease: 'power2.inOut',
  onUpdate: () => {
    brush.clear([13, 17, 23, 255]);
    brush.seed(42); brush.noiseSeed(42);
    const active = points.slice(0, Math.floor(anim.progress * points.length)).map(p => [p.x, p.y, 1.0]);
    brush.set('charcoal', '#58a6ff', 3.0);
    brush.spline(active, 0.4);
    brush.render();
  }
}, 0.5);

const FADE = 0.5;
function sceneCrossfade(outSelector, inSelector, atTime, fade = FADE) {
  tl.to(outSelector, { opacity: 0, duration: fade, ease: 'power1.inOut' }, atTime - fade / 2);
  tl.to(inSelector,  { opacity: 1, duration: fade, ease: 'power1.inOut' }, atTime - fade / 2);
}
